            return v[0], v[1]
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return v.get("x"), v.get("y")
        return None

    def _dist(a, b, c, d):
        return abs(a - c) + abs(b - d)

    def _step_toward(sx, sy, tx, ty):
        return [_sgn(tx - sx), _sgn(ty - sy)]

    def _step_away(sx, sy, tx, ty):
        return [_sgn(sx - tx), _sgn(sy - ty)]

    def _best_of(items, score_fn, reverse=False):
        best_item = None
        best_score = None
        for item in items:
            sc = score_fn(item)
            if best_item is None or (sc > best_score if reverse else sc < best_score):
                best_item = item
                best_score = sc
        return best_item

    def _collect_positions(raw):
        out = []
        if isinstance(raw, dict):
